<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue';import InitialPasswordForm from '../../../../packages/shared/src/InitialPasswordForm.vue';import {useRoute,useRouter} from 'vue-router';import {useSession} from '../../../../packages/shared/src/session';import {useTask} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const route=useRoute(),router=useRouter(),session=useSession(),task=useTask(),username=ref(''),password=ref('');
async function login(){await task.run(async()=>{await session.login(username.value,password.value,false);const target=String(route.query.redirect||'/learning');await router.replace(target.startsWith('/')&&!target.startsWith('//')?target:'/learning');});}
onBeforeUnmount(()=>{session.initialPasswordRequired=false;password.value='';});
function passwordChanged(){session.initialPasswordRequired=false;password.value='';task.error.value='';task.message.value='密码已设置，请使用新密码登录。';}
</script><template><section class="login-editorial"><div><h1>继续你的学习</h1><p>课程、笔记与每一次进步，都在这里。</p><RouterLink to="/">先浏览课程 →</RouterLink></div><div class="card login"><h2>登录天机学堂</h2><Status :busy="task.busy.value" :error="task.error.value||session.expiredMessage" :message="task.message.value"/><InitialPasswordForm v-if="session.initialPasswordRequired" :username="username" :temporary-password="password" audience="student" @completed="passwordChanged" @cancel="session.initialPasswordRequired=false;password='';task.error.value=''"/><el-form v-else label-position="top" @submit.prevent="login"><el-form-item label="账号"><el-input v-model="username" autocomplete="username" aria-label="账号" size="large"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" autocomplete="current-password" show-password aria-label="密码" size="large"/></el-form-item><el-button class="login-submit" native-type="submit" type="primary" :disabled="task.busy.value||!username||!password">登录</el-button></el-form><p>如需账号或登录帮助，请联系学校管理员。</p></div></section></template>